DROP TABLE IF EXISTS `fa_wallet_ledger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fa_wallet_ledger` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `currency` varchar(16) NOT NULL DEFAULT 'coin',
  `amount` bigint NOT NULL,
  `before` bigint NOT NULL,
  `after` bigint NOT NULL,
  `type` varchar(32) NOT NULL,
  `source_type` varchar(32) DEFAULT NULL,
  `source_id` bigint unsigned DEFAULT NULL,
  `memo` varchar(100) NOT NULL DEFAULT '',
  `createtime` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `source` (`source_type`,`source_id`),
  KEY `user_currency_time` (`user_id`,`currency`,`createtime`)
) ENGINE=InnoDB AUTO_INCREMENT=1653 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='钱包流水';
/*!40101 SET character_set_client = @saved_cs_client */;

